def process_string(s: str) -> str:
    res = []
    for c in s:
        if 'a' <= c <= 'z':
            res.append(c)
        elif c == '*':
            if res:
                res.pop()
        elif c == '#':
            res += res[:]
        elif c == '%':
            res.reverse()
    return ''.join(res)
